# In obs_0025.png, let's find the bottle bottom contact and stool legs
from PIL import Image
import numpy as np

img = np.array(Image.open('/work/observations/obs_0025.png'))

# Find the bottom contact of the blue bottle
# Look along columns 260 to 380, rows 450 to 511
for c in range(270, 380, 10):
    for r in range(511, 450, -1):
        if img[r, c, 2] > 100 and img[r, c, 0] < 50:
            print(f'Bottle at c={c}: r={r}, rgb={img[r, c]}')
            break
